import terraformMock from './mocks/terraform.json';
import terraformCycleMock from './mocks/terraform-cycle.json';
import terraformPartialMock from './mocks/terraform-partial.json';
import dockerfileMock from './mocks/dockerfile.json';
import yamlMock from './mocks/yaml.json';
import mixedMock from './mocks/mixed.json';
import type { AnalysisResult, SourceFormat } from './types';

// Mocks are real backend output, regenerated by frontend/scripts/generate_mocks.py.
// They are only used when VITE_USE_MOCK=true.
const MOCKS: Record<SourceFormat, AnalysisResult> = {
  terraform: terraformMock as AnalysisResult,
  dockerfile: dockerfileMock as AnalysisResult,
  yaml: yamlMock as AnalysisResult,
  mixed: mixedMock as AnalysisResult,
};

// Local development default; deployments set VITE_API_BASE_URL (empty = same origin).
const BASE_URL = (import.meta.env.VITE_API_BASE_URL ?? (import.meta.env.PROD ? '' : 'http://localhost:8000')).replace(
  /\/+$/,
  '',
);
const USE_MOCK = import.meta.env.VITE_USE_MOCK === 'true';

function pickMock(format: SourceFormat, source: string): AnalysisResult {
  // Temporary mock routing so the cycle and partial-analysis views can be tried
  // without a backend: examples/terraform/cyclic.tf and unsupported_expression.tf.
  if (format === 'terraform' && source.includes('aws_security_group')) {
    return terraformCycleMock as AnalysisResult;
  }
  if (format === 'terraform' && source.includes('local.')) {
    return terraformPartialMock as AnalysisResult;
  }
  return MOCKS[format];
}

export async function analyze(
  format: SourceFormat,
  source: string,
  filename?: string,
): Promise<AnalysisResult> {
  if (USE_MOCK) {
    await new Promise(resolve => setTimeout(resolve, 800));
    return pickMock(format, source);
  }

  let response: Response;
  try {
    response = await fetch(`${BASE_URL}/api/v1/validate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ source, format, filename }),
    });
  } catch {
    throw new Error("Can't reach the server. Check that the backend is running and try again.");
  }

  // Invalid source is still HTTP 200 with diagnostics; non-2xx means the request itself failed.
  if (response.status === 413) {
    throw new Error('The file is too large to analyse.');
  }
  if (response.status >= 400 && response.status < 500) {
    throw new Error(`The server rejected the request (${response.status}). Check the selected format.`);
  }
  if (!response.ok) {
    throw new Error(`The server returned an error (${response.status}). Please try again.`);
  }

  return (await response.json()) as AnalysisResult;
}

export async function analyzeMultiFile(
  format: SourceFormat,
  files: { filename: string; content: string }[],
): Promise<AnalysisResult> {
  if (USE_MOCK) {
    await new Promise(resolve => setTimeout(resolve, 800));
    return pickMock(format, files.map(f => f.content).join('\n'));
  }

  let response: Response;
  try {
    response = await fetch(`${BASE_URL}/api/v1/validate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ format, files }),
    });
  } catch {
    throw new Error("Can't reach the server. Check that the backend is running and try again.");
  }

  if (response.status === 413) {
    throw new Error('The file is too large to analyse.');
  }
  if (response.status >= 400 && response.status < 500) {
    throw new Error(`The server rejected the request (${response.status}). Check the selected format.`);
  }
  if (!response.ok) {
    throw new Error(`The server returned an error (${response.status}). Please try again.`);
  }

  return (await response.json()) as AnalysisResult;
}
